item.command:
/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire data;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data));
  always #5 clk = ~clk;
  initial begin
    "'$display("time clk rst_n data q");
    $monitor("%0t %0b %0b %0b %06b", $time, clk, rst_n, data, dut.q);
    #12 rst_n = 1;
    repeat (8) @(posedge clk);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

